import React from "react";
import { Link } from "react-router-dom";

const dateTime = (utcDate) => {
  if (!utcDate) return "";
  const date = new Date(utcDate);
  return date.toLocaleString("ru-RU", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
};

const getOutcomeColor = (outcome) => {
  // ИСПРАВЛЕНО: новые значения строк из нашего бэкенда
  if (outcome === "Win Home")
    return { text: "Прогноз: П1", colorClasses: "bg-green-600 text-white" };
  if (outcome === "Win Away")
    return {
      text: "Прогноз: П2",
      colorClasses: "bg-red-600 text-white",
    };
  if (outcome === "Draw")
    return {
      text: "Прогноз: X",
      colorClasses: "bg-yellow-500 text-black",
    };
  return null;
};

function MatchItem({ match }) {
  // ИСПРАВЛЕНО: путь к прогнозу теперь match.prediction.outcome
  const predictionData = match.prediction
    ? getOutcomeColor(match.prediction.outcome)
    : null;

  return (
    <Link
      to={`/match/${match.id}`}
      className="block bg-gray-900 rounded-lg shadow-xl border border-gray-800 overflow-hidden
                 transform hover:-translate-y-1 hover:border-gray-600 transition-all duration-300 ease-in-out"
    >
      <div className="p-4 md:p-5 flex flex-col h-full relative">
        <div className="absolute top-0 left-0 w-1 h-full bg-red-600 opacity-75"></div>
        <div className="pl-3">
          <div className="flex justify-around items-center mb-3">
            {/* Команда Хозяев */}
            <div className="flex flex-col items-center text-center w-2/5">
              <div className="h-16 w-16 bg-gray-800 rounded-full flex items-center justify-center mb-1 overflow-hidden">
                {/* Логотипы команд мы пока не добавили в БД, можно оставить заглушку или убрать img */}
                <span className="text-xl font-bold text-gray-500">
                  {match.homeTeam.name.substring(0, 1)}
                </span>
              </div>
              <span className="text-sm font-semibold text-white truncate w-full">
                {match.homeTeam.name}
              </span>
            </div>

            <span className="text-2xl font-bold text-gray-500">VS</span>

            {/* Команда Гостей */}
            <div className="flex flex-col items-center text-center w-2/5">
              <div className="h-16 w-16 bg-gray-800 rounded-full flex items-center justify-center mb-1 overflow-hidden">
                <span className="text-xl font-bold text-gray-500">
                  {match.awayTeam.name.substring(0, 1)}
                </span>
              </div>
              <span className="text-sm font-semibold text-white truncate w-full">
                {match.awayTeam.name}
              </span>
            </div>
          </div>

          {/* Плашка прогноза */}
          {predictionData && (
            <div className="my-3 text-center">
              <div className="flex flex-col gap-1 items-center">
                <span
                  className={`px-4 py-1.5 text-xs font-bold rounded-full shadow-md ${predictionData.colorClasses}`}
                >
                  {predictionData.text}
                </span>
                {/* Добавим предсказанный счет для наглядности */}
                <span className="text-gray-400 text-[10px] uppercase tracking-tighter">
                  Ожидаемый счет: {match.prediction.exact_score}
                </span>
              </div>
            </div>
          )}

          {/* Результат матча (если завершен) */}
          {match.status === "FINISHED" && (
            <p className="text-center text-lg font-bold my-2 text-yellow-500">
              {match.score.homeTeam} - {match.score.awayTeam}
            </p>
          )}

          {!predictionData && match.status !== "FINISHED" && (
            <div className="my-3 h-8 flex items-center justify-center">
              <span className="text-gray-600 text-xs italic">
                Прогноз готовится...
              </span>
            </div>
          )}

          <div className="mt-auto text-center text-xs text-gray-400 pt-3 border-t border-gray-800">
            {dateTime(match.utcDate)}
          </div>
        </div>
      </div>
    </Link>
  );
}

export default MatchItem;
